'use strict';

// MODULES //

var arraylikefcn = require( '@stdlib/assert/tools/array-like-function' );
var isField = require( '@stdlib/plot/vega/base/assert/is-field' );


// MAIN //

/**
* Tests whether an input value is an array of field instances.
*
* @name isFieldArray
* @type {Function}
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is an array of field instances
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var v = new Field({
*     'field': 'amount'
* });
* var bool = isFieldArray( [ v ] );
* // returns true
*
* bool = isFieldArray( {} );
* // returns false
*
* bool = isFieldArray( 'foo' );
* // returns false
*/
var isFieldArray = arraylikefcn( isField );


// EXPORTS //

module.exports = isFieldArray;
